-- Isolated restored database only; entire suite rolls back. No formal test questions are imported.
begin;
set local search_path=v2,extensions,public;
create schema materials_test;
create function materials_test.ok(label text, value boolean) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function materials_test.reject(label text,statement text) returns void language plpgsql as $$declare rejected boolean=false;begin begin execute statement;exception when others then rejected=true;end;perform materials_test.ok(label,rejected);end$$;
select materials_test.ok('27 real images / 18 MV / 4 types',(select count(*)=27 and count(*) filter(where kind='mv')=18 and count(distinct kind)=4 from scenes where image_status='approved'));
select materials_test.ok('only MV has time / official fixed version',(select bool_and((kind='mv' and timestamp_seconds is not null and canonical_work_url like 'https://www.youtube.com/watch?v=%') or (kind<>'mv' and timestamp_seconds is null)) from scenes));
select materials_test.ok('city and song / lyric overlay closed',not exists(select 1 from scenes where (kind in ('song_title','lyric') or association_precision in ('city','region','unverified')) and overlay_eligible));
select materials_test.ok('pending port hidden from public catalog',not exists(select 1 from jsonb_array_elements(catalog()->'places') p where p->>'id'='shuinandong-port'));
select materials_test.ok('public catalog counts 24 / 26',(select jsonb_array_length(catalog()->'places')=24 and sum(jsonb_array_length(p->'scenes'))=26 from jsonb_array_elements(catalog()->'places') p));
select materials_test.ok('30 private formal questions / 20 + 10',(select count(*)=30 and count(*) filter(where challenge_type='multiple_choice')=20 and count(*) filter(where challenge_type='map_guess')=10 from questions where published));
select materials_test.ok('map radius 1km / concrete targets',not exists(select 1 from questions q join scenes s on s.id=q.reference_scene_id where q.challenge_type='map_guess' and (q.correct_radius_m<>1000 or s.association_precision in ('city','region','unverified'))));
select materials_test.ok('questions have separate opaque image URLs',not exists(select 1 from questions q join scenes s on s.id=q.reference_scene_id where q.image_url=s.image_url));
select materials_test.ok('30 days / no repeated questions',(select count(*)=30 and count(distinct question_id)=30 and max(challenge_date)-min(challenge_date)=29 from challenge_schedule));
select materials_test.ok('private answers cannot be directly read',not has_table_privilege('authenticated','v2.questions','select') and not has_table_privilege('anon','v2.questions','select'));
select materials_test.reject('null dimensions cannot approve',$q$update scenes set image_width=null where id='samaritaine-jay-1'$q$);
select materials_test.reject('missing user approval cannot approve',$q$update scenes set image_provenance=image_provenance-'userReview' where id='samaritaine-jay-1'$q$);
select materials_test.reject('non-MV fake timestamp rejected',$q$update scenes set timestamp_seconds=60 where id='lee-tung-kay-title'$q$);
select materials_test.reject('city overlay rejected',$q$update scenes set overlay_eligible=true where id='vladivostok-jay-cover'$q$);
select materials_test.reject('pending scene cannot publish question',$q$update questions set reference_scene_id='shuinandong-port-jj-1' where id='mc-01'$q$);
select materials_test.reject('question URL join rejected',$q$update questions set image_url=(select image_url from scenes where id='mont-saint-michel-jay-1') where id='mc-01'$q$);
do $$declare actor uuid=gen_random_uuid();payload jsonb;fix jsonb;pt geography;q questions;answer jsonb;
begin
 insert into auth.users(id,email_confirmed_at) values(actor,now());insert into profiles(id,nickname) values(actor,'隔离素材验收');
 payload=public.pilgrimage_v2(actor,'challenges');
 perform materials_test.ok('only Shanghai current / past challenge readable',jsonb_array_length(payload)=1);
 perform materials_test.ok('pre-answer payload omits answers sources and scene IDs',not exists(select 1 from jsonb_array_elements(payload) p where p ?| array['correct_option','answer_location_id','answer_latitude','answer_longitude','explanation','source_url','reference_scene_id']));
 perform materials_test.ok('title alias search works',jsonb_array_length(public.pilgrimage_v2(null,'search','{"query":"喜帖街"}'))=1);
 perform public.pilgrimage_v2(actor,'submit',jsonb_build_object('id',gen_random_uuid(),'submission_type','new_location','artist','谢安琪','title','囍帖街','place_name','利东街','association_type','song_title','association_excerpt','囍帖街','canonical_work_url','https://music.apple.com/album/binary/387758767'));
 perform public.pilgrimage_v2(actor,'submit',jsonb_build_object('id',gen_random_uuid(),'submission_type','new_location','artist','周杰伦','title','爱你没差','place_name','格林威治','association_type','lyric','association_excerpt','我占据 格林威治 守候着你'));
 perform materials_test.ok('song / lyric submissions retain their type and excerpt',(select count(*)=2 and bool_and(association_excerpt<>'') from submissions where user_id=actor and association_type in ('song_title','lyric')));
 perform public.pilgrimage_v2(actor,'submit',jsonb_build_object('id',gen_random_uuid(),'submission_type','new_location','artist','旧客户端','title','未分类记录','place_name','未分类地点'));
 perform materials_test.ok('old submission stays unclassified',(select association_type is null from submissions where user_id=actor and title='未分类记录'));
 perform materials_test.reject('lyric without excerpt rejected',format('select public.pilgrimage_v2(%L,''submit'',%L)',actor,jsonb_build_object('id',gen_random_uuid(),'submission_type','new_location','artist','周杰伦','title','爱你没差','place_name','格林威治','association_type','lyric')::text));
 perform materials_test.reject('unknown association type rejected',format('select public.pilgrimage_v2(%L,''submit'',%L)',actor,jsonb_build_object('id',gen_random_uuid(),'submission_type','new_location','artist','歌手','title','作品','place_name','地点','association_type','unknown')::text));
 perform materials_test.reject('pending place cannot be favorited',format('select public.pilgrimage_v2(%L,''favorite'',''{"location_id":"shuinandong-port","enabled":true}'')',actor));
 select geo into pt from locations where id='vladivostok';
 pt=st_project(pt,199,radians(90));fix=jsonb_build_object('latitude',st_y(pt::geometry),'longitude',st_x(pt::geometry),'accuracy',10,'capturedAt',now(),'ageMillis',0,'mock',false);
 perform public.pilgrimage_v2(actor,'verify_visit',jsonb_build_object('location_id','vladivostok','fix',fix));
 perform materials_test.ok('city anchor accepts 199m actual arrival',exists(select 1 from content where user_id=actor and location_id='vladivostok' and kind='visit'));
 select geo into pt from locations where id='greenwich';pt=st_project(pt,201,radians(90));fix=fix||jsonb_build_object('latitude',st_y(pt::geometry),'longitude',st_x(pt::geometry));
 perform materials_test.reject('region anchor rejects 201m',format('select public.pilgrimage_v2(%L,''verify_visit'',%L)',actor,jsonb_build_object('location_id','greenwich','fix',fix)::text));
 delete from challenge_schedule where challenge_date=(now() at time zone 'Asia/Shanghai')::date or question_id='map-02';
 insert into challenge_schedule values((now() at time zone 'Asia/Shanghai')::date,'map-02');select * into q from questions where id='map-02';
 pt=st_setsrid(st_makepoint(q.answer_longitude,q.answer_latitude),4326)::geography;pt=st_project(pt,999,radians(90));
 answer=public.pilgrimage_v2(actor,'answer',jsonb_build_object('question_id',q.id,'latitude',st_y(pt::geometry),'longitude',st_x(pt::geometry)));
 perform materials_test.ok('map 999m correct', (answer->>'correct')::boolean);
 answer=public.pilgrimage_v2(actor,'answer',jsonb_build_object('question_id',q.id,'latitude',q.answer_latitude+0.2,'longitude',q.answer_longitude));
 perform materials_test.ok('repeat answer is practice only',(answer->>'practice')::boolean);
end $$;
rollback;
